/* One persisted board per book; camera and edit history are independent of Reader. */
const Board={bookId:null,edit:false,selected:new Set(),connectionId:null,undo:[],redo:[],camera:{x:40,y:40,zoom:1},gesture:null,
  open(book){if(this.bookId!==book.id){this.bookId=book.id;this.edit=false;this.selected.clear();this.undo=[];this.redo=[];this.camera={x:40,y:40,zoom:1,...ArchiveModel.board(book).viewport}}$('#boardPanel').innerHTML=`<div class="board-tools"><button id="boardMode">View mode</button><select id="newCardType" aria-label="Card type"><option value="character">Character</option><option value="event">Event</option><option value="clue">Clue / Theory</option><option value="quote">Quote</option><option value="note">Free Note</option><option value="image">Image</option></select><button id="addCard">＋ Card</button><button id="connectCards">Connect selected</button><button id="alignCards">Align top</button><button id="distributeCards">Distribute</button><button id="undoBoard">Undo</button><button id="redoBoard">Redo</button><input id="boardSearch" aria-label="Search cards" placeholder="Search cards…"><select id="boardFilter" aria-label="Filter card type"><option value="">All types</option><option value="character">Character</option><option value="event">Event</option><option value="clue">Clue / Theory</option><option value="quote">Quote</option><option value="note">Free Note</option><option value="image">Image</option></select></div><div class="board-layout"><div id="boardCanvas" tabindex="0" aria-label="Story Board canvas"><div id="boardWorld"><svg id="boardLines" width="12000" height="12000"></svg><div id="boardCards"></div></div><div class="camera-tools"><button id="zoomOut" aria-label="Zoom out">−</button><span id="zoomValue"></span><button id="zoomIn" aria-label="Zoom in">＋</button><button id="fitBoard">Fit to Content</button><button id="lastPinned">Go to Last Pinned Card</button></div><svg id="minimap" viewBox="0 0 200 120" aria-label="Board minimap"></svg></div><aside id="cardInspector"><p>Select a card to view its details. Shift-click to select more.</p></aside></div><div id="boardSaveState" role="status">Saved</div>`;
    $('#boardMode').onclick=()=>{this.edit=!this.edit&&!this.mobile();this.refresh()};$('#addCard').onclick=()=>{if(!this.allowed())return;const type=$('#newCardType').value;this.change(board=>{const n=board.cards.length;const c={id:crypto.randomUUID(),type,title:type==='note'?'New note':'New '+type,body:'',color:'#9655ff',x:(n%4)*290,y:Math.floor(n/4)*230,w:260,h:200};board.cards.push(c);this.selected=new Set([c.id])})};
    $('#connectCards').onclick=()=>{if(!this.allowed()||this.selected.size!==2)return message('Select exactly two cards with Shift-click.');this.change(board=>board.connections.push({id:crypto.randomUUID(),from:[...this.selected][0],to:[...this.selected][1],label:'',bend:0}))};
    $('#alignCards').onclick=()=>{if(!this.allowed())return;this.change(board=>{const cs=board.cards.filter(c=>this.selected.has(c.id)),y=Math.min(...cs.map(c=>c.y));cs.forEach(c=>c.y=y)})};$('#distributeCards').onclick=()=>{if(!this.allowed())return;this.change(board=>{const cs=board.cards.filter(c=>this.selected.has(c.id)).sort((a,b)=>a.x-b.x);if(cs.length<3)return;const left=cs[0].x,right=cs.at(-1).x,step=(right-left)/(cs.length-1);cs.forEach((c,i)=>c.x=left+i*step)})};
    $('#undoBoard').onclick=()=>this.history(false);$('#redoBoard').onclick=()=>this.history(true);$('#boardSearch').oninput=()=>this.draw();$('#boardFilter').onchange=()=>this.draw();$('#zoomIn').onclick=()=>this.zoom(1.2);$('#zoomOut').onclick=()=>this.zoom(1/1.2);$('#fitBoard').onclick=()=>this.fit();$('#lastPinned').onclick=()=>{const board=this.data();const card=board.cards.find(c=>c.id===board.lastPinnedId)||[...board.cards].reverse().find(c=>c.type==='quote');if(card)this.focus(card);else message('No pinned Quote Cards yet.')};
    const canvas=$('#boardCanvas');canvas.onwheel=e=>{e.preventDefault();this.zoom(e.deltaY<0?1.1:1/1.1,e.offsetX,e.offsetY)};canvas.onpointerdown=e=>this.down(e);canvas.onpointermove=e=>this.move(e);canvas.onpointerup=e=>this.up(e);canvas.onpointercancel=()=>{this.gesture=null;this.draw()};canvas.onkeydown=e=>this.key(e);
    $('#minimap').onclick=e=>{const bounds=this.bounds(),rect=e.currentTarget.getBoundingClientRect();this.camera.x=-((e.clientX-rect.left)/rect.width*bounds.w+bounds.x)*this.camera.zoom+canvas.clientWidth/2;this.camera.y=-((e.clientY-rect.top)/rect.height*bounds.h+bounds.y)*this.camera.zoom+canvas.clientHeight/2;this.cameraSave();this.draw()};this.refresh();
  },
  mobile(){return matchMedia('(max-width:700px)').matches},allowed(){return this.edit&&!this.mobile()},data(){return ArchiveModel.board(books.find(b=>b.id===this.bookId)||{})},
  refresh(){if(!$('#boardCanvas')||this.bookId!==activeBookId)return;if(this.mobile())this.edit=false;$('#boardMode').textContent=this.mobile()?'View only · mobile':this.edit?'Edit mode':'View mode';for(const id of ['newCardType','addCard','connectCards','alignCards','distributeCards','undoBoard','redoBoard'])$('#'+id).disabled=!this.allowed();$('#undoBoard').disabled=!this.allowed()||!this.undo.length;$('#redoBoard').disabled=!this.allowed()||!this.redo.length;this.draw();this.inspect()},
  async change(fn){if(this.saving)return message('Please wait for the current board save.');const previous=structuredClone(this.data()),next=structuredClone(previous);try{fn(next);this.saving=true;$('#boardSaveState').textContent='Saving…';await updateBook(this.bookId,b=>({...b,board:{...ArchiveModel.mergeBoard(ArchiveModel.board(b),previous,next),viewport:{...this.camera}}}));this.undo.push({before:previous,after:next});this.redo=[];$('#boardSaveState').textContent='Saved';this.refresh()}catch(e){$('#boardSaveState').textContent='Not saved';this.refresh();serious(e)}finally{this.saving=false}},
  async history(redo){if(!this.allowed()||this.saving)return;const from=redo?this.redo:this.undo,to=redo?this.undo:this.redo;if(!from.length)return;const entry=from.at(-1);try{await updateBook(this.bookId,b=>({...b,board:ArchiveModel.mergeBoard(ArchiveModel.board(b),redo?entry.before:entry.after,redo?entry.after:entry.before)}));from.pop();to.push(entry);this.selected.clear();this.refresh();message('Saved')}catch(e){serious(e)}},
  bounds(){const cs=this.data().cards;if(!cs.length)return {x:0,y:0,w:1000,h:600};const x=Math.min(...cs.map(c=>c.x))-40,y=Math.min(...cs.map(c=>c.y))-40;return {x,y,w:Math.max(...cs.map(c=>c.x+c.w))-x+40,h:Math.max(...cs.map(c=>c.y+c.h))-y+40}},
  fit(){const b=this.bounds(),canvas=$('#boardCanvas');this.camera.zoom=Math.min(1.5,canvas.clientWidth/b.w,canvas.clientHeight/b.h);this.camera.x=-b.x*this.camera.zoom;this.camera.y=-b.y*this.camera.zoom;this.draw();this.cameraSave()},focus(card){const c=$('#boardCanvas');this.camera.x=c.clientWidth/2-(card.x+card.w/2)*this.camera.zoom;this.camera.y=c.clientHeight/2-(card.y+card.h/2)*this.camera.zoom;this.selected=new Set([card.id]);this.draw();this.inspect();this.cameraSave()},
  zoom(factor,x,y){const canvas=$('#boardCanvas');x=x??canvas.clientWidth/2;y=y??canvas.clientHeight/2;const old=this.camera.zoom,next=Math.min(2.5,Math.max(.15,old*factor));this.camera.x=x-(x-this.camera.x)*next/old;this.camera.y=y-(y-this.camera.y)*next/old;this.camera.zoom=next;this.draw();this.cameraSave()},
  cameraSave(){clearTimeout(this.cameraTimer);const id=this.bookId,camera={...this.camera};this.cameraTimer=setTimeout(async()=>{try{await updateBook(id,b=>({...b,board:{...ArchiveModel.board(b),viewport:camera}}));if($('#boardSaveState'))$('#boardSaveState').textContent='Saved'}catch(e){serious(e)}},300)},
  draw(override){if(!$('#boardWorld'))return;const board=override||this.data(),query=$('#boardSearch').value.toLowerCase(),filter=$('#boardFilter').value;$('#boardWorld').style.transform=`translate(${this.camera.x}px,${this.camera.y}px) scale(${this.camera.zoom})`;$('#zoomValue').textContent=Math.round(this.camera.zoom*100)+'%';
    $('#boardCards').innerHTML=board.cards.filter(c=>(!filter||c.type===filter)&&(!query||(c.title+' '+c.body).toLowerCase().includes(query))).map(c=>`<div class="canvas-card ${this.selected.has(c.id)?'selected':''}" data-card="${escapeHTML(c.id)}" style="left:${c.x}px;top:${c.y}px;width:${c.w}px;height:${c.h}px;--card-color:${/^#[0-9a-f]{6}$/i.test(c.color)?c.color:'#9655ff'}" role="button" tabindex="0" aria-label="${escapeHTML(c.type+': '+c.title)}"><span class="card-category">${escapeHTML(c.type)}</span><h3>${escapeHTML(c.title)}</h3>${c.image?`<img src="${assetURL(c.image)}" alt="">`:''}<p>${escapeHTML(c.body)}</p>${(c.source?.unresolved||(c.type==='quote'&&!c.source))?'<span class="source-warning">Source Unavailable</span>':''}${this.allowed()?'<span class="resize-card" aria-label="Resize card">◢</span>':''}</div>`).join('');
    $('#boardLines').innerHTML=board.connections.map(e=>{const a=board.cards.find(c=>c.id===e.from),b=board.cards.find(c=>c.id===e.to);if(!a||!b)return '';const x=a.x+a.w/2,y=a.y+a.h/2,u=b.x+b.w/2,v=b.y+b.h/2,cx=(x+u)/2+(e.bend||0),cy=(y+v)/2-(e.bend||0);return `<g data-connection="${escapeHTML(e.id)}"><path d="M${x},${y} Q${cx},${cy} ${u},${v}" class="connection ${this.connectionId===e.id?'selected':''}"/><text x="${cx}" y="${cy-8}">${escapeHTML(e.label||'')}</text>${this.allowed()&&this.connectionId===e.id?`<circle data-bend="${escapeHTML(e.id)}" cx="${cx}" cy="${cy}" r="9"/>`:''}</g>`}).join('');
    const bounds=this.bounds();$('#minimap').innerHTML=board.cards.map(c=>`<rect x="${(c.x-bounds.x)/bounds.w*200}" y="${(c.y-bounds.y)/bounds.h*120}" width="${Math.max(2,c.w/bounds.w*200)}" height="${Math.max(2,c.h/bounds.h*120)}" fill="${/^#[0-9a-f]{6}$/i.test(c.color)?c.color:'#9655ff'}"/>`).join('');
    $('#boardCards').querySelectorAll('[data-card]').forEach(el=>el.onkeydown=e=>{if(e.key==='Enter'){this.selected=new Set([el.dataset.card]);this.inspect();this.draw()}});
  },
  down(e){if(e.button!==0)return;const card=e.target.closest('[data-card]'),edge=e.target.closest('[data-connection]'),canvas=$('#boardCanvas');canvas.focus();const before=structuredClone(this.data());
    if(edge){this.connectionId=edge.dataset.connection;this.selected.clear();this.inspect();this.draw();if(e.target.closest('[data-bend]')&&this.allowed())this.gesture={kind:'bend',id:this.connectionId,before,x:e.clientX,y:e.clientY};}
    else if(card){this.connectionId=null;const id=card.dataset.card;if(e.shiftKey){this.selected.has(id)?this.selected.delete(id):this.selected.add(id)}else if(!this.selected.has(id))this.selected=new Set([id]);this.inspect();this.draw();if(this.allowed())this.gesture={kind:e.target.closest('.resize-card')?'resize':'cards',id,before,x:e.clientX,y:e.clientY};}
    else {this.selected.clear();this.connectionId=null;this.inspect();this.draw();this.gesture={kind:'pan',x:e.clientX,y:e.clientY,camera:{...this.camera}}}
    if(this.gesture)canvas.setPointerCapture(e.pointerId);
  },
  move(e){const g=this.gesture;if(!g)return;const dx=(e.clientX-g.x)/this.camera.zoom,dy=(e.clientY-g.y)/this.camera.zoom;if(g.kind==='pan'){this.camera.x=g.camera.x+e.clientX-g.x;this.camera.y=g.camera.y+e.clientY-g.y;this.draw();return}const next=structuredClone(g.before);if(g.kind==='cards')next.cards.forEach(c=>{if(this.selected.has(c.id)){c.x=Math.max(0,c.x+dx);c.y=Math.max(0,c.y+dy)}});if(g.kind==='resize'){const c=next.cards.find(c=>c.id===g.id);c.w=Math.max(140,c.w+dx);c.h=Math.max(100,c.h+dy)}if(g.kind==='bend'){const edge=next.connections.find(c=>c.id===g.id);edge.bend=(edge.bend||0)+dx}g.next=next;this.draw(next)},
  up(){const g=this.gesture;this.gesture=null;if(!g)return;if(g.kind==='pan')return this.cameraSave();if(g.next&&this.allowed())this.change(board=>Object.assign(board,g.next))},
  inspect(){const target=$('#cardInspector');if(!target)return;const board=this.data(),edge=board.connections.find(e=>e.id===this.connectionId),card=board.cards.find(c=>this.selected.has(c.id));
    if(edge){target.innerHTML=`<h3>Connection</h3><label>Label<input id="edgeLabel" value="${escapeHTML(edge.label||'')}" ${this.allowed()?'':'disabled'}></label><label>Curve bend<input id="edgeBend" type="number" value="${edge.bend||0}" ${this.allowed()?'':'disabled'}></label><button id="saveEdge" ${this.allowed()?'':'disabled'}>Save connection</button><button id="deleteEdge" ${this.allowed()?'':'disabled'}>Delete connection</button>`;$('#saveEdge').onclick=()=>this.change(board=>{const e=board.connections.find(e=>e.id===edge.id);e.label=$('#edgeLabel').value;e.bend=Number($('#edgeBend').value)||0});$('#deleteEdge').onclick=()=>this.change(board=>board.connections=board.connections.filter(e=>e.id!==edge.id));return;}
    if(!card){target.innerHTML='<p>Select a card. Shift-click for multiple selection. Drag empty space to pan.</p>';return;}
    target.innerHTML=`<span class="card-category">${escapeHTML(card.type)}</span><label>Title<input id="cardTitle" value="${escapeHTML(card.title)}" ${this.allowed()?'':'disabled'}></label><label>Description<textarea id="cardBody" rows="6" ${this.allowed()?'':'disabled'}>${escapeHTML(card.body)}</textarea></label><label>Color<input id="cardColor" type="color" value="${/^#[0-9a-f]{6}$/i.test(card.color)?card.color:'#9655ff'}" ${this.allowed()?'':'disabled'}></label><label>Optional image<input id="cardImage" type="file" accept="image/png,image/jpeg,image/webp" ${this.allowed()?'':'disabled'}></label><button id="saveCard" ${this.allowed()?'':'disabled'}>Save card</button><button id="deleteCard" ${this.allowed()?'':'disabled'}>Delete selected</button>${card.type==='quote'?`${card.source?'<button id="jumpSource">Jump to Source</button>':''}<button id="relinkSource">Relink Source</button>${!card.source||card.source.unresolved?'<p>Source Unavailable</p>':''}`:''}`;
    $('#saveCard').onclick=async()=>{const title=$('#cardTitle').value,body=$('#cardBody').value,color=$('#cardColor').value,file=$('#cardImage').files[0];try{if(file)await validateImage(file);this.change(board=>{const c=board.cards.find(c=>c.id===card.id);c.title=title;c.body=body;if(file)c.image=file;if(c.highlightId){message('Quote color follows its Reader highlight.');}else c.color=color})}catch(e){serious(e)}};
    $('#deleteCard').onclick=()=>{if(confirm('Delete the selected cards and their connections?'))this.deleteSelected()};$('#jumpSource')?.addEventListener('click',async()=>{setWorkspaceTab('reader');await Reader.open(books.find(b=>b.id===this.bookId));Reader.jump(card.source)});$('#relinkSource')?.addEventListener('click',async()=>{Reader.relinkCardId=card.id;setWorkspaceTab('reader');await Reader.open(books.find(b=>b.id===this.bookId));message('Select the replacement passage, then choose Relink selected Quote.',true)});
  },
  deleteSelected(){if(!this.allowed())return;this.change(board=>{board.cards=board.cards.filter(c=>!this.selected.has(c.id));board.connections=board.connections.filter(e=>!this.selected.has(e.from)&&!this.selected.has(e.to));this.selected.clear()})},
  key(e){if(/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||e.target.isContentEditable)return;if(e.key==='Escape'){this.selected.clear();this.connectionId=null;this.refresh()}if(!this.allowed())return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();this.history(e.shiftKey)}if((e.key==='Delete'||e.key==='Backspace')&&this.selected.size){e.preventDefault();if(confirm('Delete selected cards?'))this.deleteSelected()}}
};
